--region public
---刷新cell
---@param storeType OverseaStoreConstants.StoreType
---@param data table
function OverseaStoreOptionalGiftCell:RefreshCell(storeType, data)
    self._storeType = storeType
    self._cellData = data
    self._choice = string.split(data.choiceRewardsId, ',')

    self:RefreshCellState(data)
    self:RefreshGoods(data)
    self:RefreshOptionalGoods(data)
    self:RefreshPrice(data)
    self:RefreshNewIcon(storeType, data)

end
