--region private
---刷新cell状态
function OverseaStoreOptionalGiftCell:RefreshCellState(data)
    local isSoldOut = OverseaStoreUtils.ProductIsSoldOut(data)
    KTool.SetActive(self.Finish, isSoldOut)

    local isFree = OverseaStoreUtils.ProductIsFree(data)
    CfUtils.SetUISwitchImage(self.ImgBg, isFree and 1 or 2)
    CfUtils.SetActive(self.FreeGiftTitle, isFree)
end

---刷新道具
function OverseaStoreOptionalGiftCell:RefreshGoods(data)
    CfUtils.RefeshGoodGo2(self.GoodNode, data.rewards[1].goodsId, data.rewards[1].num,nil, nil)

    -- 库存
    if checkNumber(data.stock) == -1 then
        KTool.SetActive(self.Stock, false)
    else
        KTool.SetActive(self.Stock, true)
        CfUtils.FillText(self.StockTextDesc2, data.currentStock)
    end

    local tabType = checkInt(data.iconId)
    if tabType == TagType.Discount then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(tonumber(data.iconTitle) * 100)))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ImgRecommend, false)
    elseif tabType == TagType.Recommend then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ImgRecommend, true)
    elseif tabType == TagType.All then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(tonumber(data.iconTitle) * 100)))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ImgRecommend, true)
    else
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ImgRecommend, false)
    end
    
    -- 充值积分
    if isNotNull(data.payPoint) then
        CfUtils.SetActive(self.RechargePoints, true)
        CfUtils.FillText(self.PointTextDesc2, string.format('x%d', checkInt(data.payPoint)))
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.Currency.CumulativeScore)
        CfUtils.FillImage(self.PointImgGoodsIcon, goodsVo.photoPath)
    else
        CfUtils.SetActive(self.RechargePoints, false)
    end
end

---刷新可选道具
function OverseaStoreOptionalGiftCell:RefreshOptionalGoods(data)
    for i = 1, self.Layout.childCount do
        local go = self.Layout:GetChild(i - 1)
        CfUtils.SetActive(go, false)
    end

    for i = 1, 3 do
        local rewardGroup = checkTable(data['rewardGroup' .. i])
        if next(rewardGroup) ~= nil then
            local go = nil
            if i > self.Layout.childCount then
                go = CfUtils.InstantiateGo(self.BtnRewardNode.gameObject, self.Layout)
            else
                go = self.Layout:GetChild(i - 1)
            end
            CfUtils.SetActive(go, true)
            
            local emptyNode = go.transform:Find('Root/Empty')
            local contentNode = go.transform:Find('Root/Content')
            local choiceId = checkInt(self._choice[i])
            if choiceId == 0 then
                CfUtils.SetActive(emptyNode, true)
                CfUtils.SetActive(contentNode, false)
            else
                CfUtils.SetActive(emptyNode, false)
                CfUtils.SetActive(contentNode, true)
                local goodsNode = contentNode:Find('GoodNode')
                CfUtils.RefeshGoodGo2(goodsNode, rewardGroup[choiceId].goodsId, rewardGroup[choiceId].num)
            end
            
            SetButtonAction(go, function()
                local isSoldOut = OverseaStoreUtils.ProductIsSoldOut(data)
                if isSoldOut then
                    GameUtils.Toast(localize("商品已售罄"))
                    return
                end
                CfUtils.DialogOpen(Constants.UITypeIds.OverseaStoreOptionalGiftPopup, {data = data, index = i})
            end)
        end
    end
end

---刷新价格
function OverseaStoreOptionalGiftCell:RefreshPrice(data)
    local isSoldOut = OverseaStoreUtils.ProductIsSoldOut(data)
    if isSoldOut then
        CfUtils.SetActive(self.Number1, false)
        CfUtils.SetActive(self.Number2, false)
        CfUtils.SetActive(self.BtnBuy, false)
        CfUtils.SetActive(self.Stock, false)
        CfUtils.SetActive(self.Finish, true)
        return
    end
    
    local selectedNum = self:GetSelectedNum()
    local rewardsNum = self:GetRewardsNum()
    if selectedNum == 0 then
        -- 未选择
        CfUtils.SetActive(self.Number1, true)
        CfUtils.SetActive(self.Number2, false)
        CfUtils.SetActive(self.BtnBuy, false)
        CfUtils.SetActive(self.Stock, true)
        CfUtils.SetActive(self.Finish, false)
    elseif selectedNum == rewardsNum then
        -- 全部选择
        CfUtils.SetActive(self.Number1, false)
        CfUtils.SetActive(self.Number2, false)
        CfUtils.SetActive(self.BtnBuy, true)
        CfUtils.SetActive(self.Stock, true)
        CfUtils.SetActive(self.Finish, false)
        local isFree = OverseaStoreUtils.ProductIsFree(data)
        if isFree then
            CfUtils.SetActive(self.BtnBuyFree, true)
            CfUtils.SetActive(self.BtnBuyPaid, false)
        else
            CfUtils.SetActive(self.BtnBuyFree, false)
            CfUtils.SetActive(self.BtnBuyPaid, true)
        end
        
        if isNotNull(data.payPoint) then
            local windowPricesId = CfUtils.GetWindowsPriceId(data)
            CfUtils.FillText(self.BtnBuyTextDesc, CfUtils.GetCustomDisplayPrice(windowPricesId, data.channelProductId, 24))
            CfUtils.SetActive(self.BtnBuyImgGoodsIcon, false)
        elseif next(checkTable(data.prices)) then
            CfUtils.FillText(self.BtnBuyTextDesc, data.prices[1].current)
            CfUtils.SetActive(self.BtnBuyImgGoodsIcon, true)
            local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.prices[1].currency))
            CfUtils.FillImage(self.BtnBuyImgGoodsIcon, currencyVo.photoPath)
        end
        SetButtonAction(self.BtnBuy, function()
            OverseaStoreMgr:OptionalGiftBuy(data)
        end)
    else
        -- 部分选择
        CfUtils.SetActive(self.Number1, false)
        CfUtils.SetActive(self.Number2, true)
        CfUtils.SetActive(self.BtnBuy, false)
        CfUtils.SetActive(self.Stock, true)
        CfUtils.SetActive(self.Finish, false)
        CfUtils.FillText(self.Number2TextDesc, string.format("<color=#FF009C>%d</color>/%d", selectedNum, rewardsNum))
    end
end

---刷新new标识
function OverseaStoreOptionalGiftCell:RefreshNewIcon(storeType, data)
    CfUtils.SetActive(self.ImgNew, OverseaStoreMgr:IsNewStoreProduct(storeType, data.productId))
end

---获取选中数量
function OverseaStoreOptionalGiftCell:GetSelectedNum()
    local num = 0
    for i = 1, 3 do
        local choiceId = checkInt(self._choice[i])
        if choiceId > 0 then
            num = num + 1
        end
    end
    return num
end

---获取选中奖励数量
function OverseaStoreOptionalGiftCell:GetRewardsNum()
    local num = 0
    for i = 1, 3 do
        local rewardGroup = checkTable(self._cellData['rewardGroup' .. i])
        if next(rewardGroup) ~= nil then
            num = num + 1
        end
    end
    return num
end

--endregion private

return OverseaStoreOptionalGiftCell